def nest(flat, shape):
    if not shape:
        return flat[0]
    out = list(flat)
    for d in reversed(shape[1:]):
        out = [out[i:i + d] for i in range(0, len(out), d)]
    return out


def flat(x):
    """(flat floats, shape) of a nested list, or None if not rectangular."""
    if isinstance(x, bool):
        return None
    if isinstance(x, (int, float)):
        return [float(x)], []
    if not isinstance(x, (list, tuple)):
        try:
            return [float(x)], []        # e.g. a numeric scalar type
        except Exception:  # noqa: BLE001
            return None
    shape, cur = [], x
    while isinstance(cur, (list, tuple)):
        shape.append(len(cur))
        if not cur:
            break
        cur = cur[0]
    vals, stack = [], [(x, 0)]
    while stack:
        node, d = stack.pop()
        if d == len(shape):
            if isinstance(node, (list, tuple)) or isinstance(node, bool):
                return None
            vals.append(float(node))
            continue
        if not isinstance(node, (list, tuple)) or len(node) != shape[d]:
            return None
        for e in reversed(node):
            stack.append((e, d + 1))
    return vals, shape


